import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { format, formatDistanceToNow } from 'date-fns';
import { 
  ChatBubbleLeftRightIcon,
  UserIcon,
  BuildingOfficeIcon,
  ArrowRightIcon,
  ExclamationCircleIcon,
  CheckCircleIcon,
  ClockIcon,
  PaperAirplaneIcon,
  FunnelIcon,
  MagnifyingGlassIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  EnvelopeIcon,
  EnvelopeOpenIcon,
  ArrowPathIcon,
  XMarkIcon,
  DocumentTextIcon,
  InboxIcon
} from '@heroicons/react/24/outline';
import { interceptAPI } from '../services/api';
import { toast } from 'react-toastify';

const InterceptedMessages = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [expandedConversations, setExpandedConversations] = useState(new Set());
  const [forwardMessage, setForwardMessage] = useState('');
  const [adminNote, setAdminNote] = useState('');
  const [replyMessage, setReplyMessage] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [showDetails, setShowDetails] = useState({});
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastRefreshed, setLastRefreshed] = useState(new Date());

  // Fetch intercepted conversations with auto-refresh
  const { data: conversationsResponse, isLoading, refetch, isFetching } = useQuery({
    queryKey: ['intercepted-conversations'],
    queryFn: async () => {
      const response = await interceptAPI.getInterceptedConversations();
      return response.data;
    },
    refetchInterval: 10000, // Refresh every 10 seconds
    refetchIntervalInBackground: true,
    staleTime: 0, // Consider data stale immediately for manual refreshes
    gcTime: 5 * 60 * 1000, // Keep cache for 5 minutes (renamed from cacheTime)
  });
  
  // Extract conversations array from the response structure
  const conversations = conversationsResponse?.data?.conversations || [];
  const apiStats = conversationsResponse?.data?.statusCounts || {
    all: 0,
    pending: 0,
    forwarded: 0,
    replied: 0,
    awaiting_reply: 0
  };
  const unreadCount = conversationsResponse?.data?.unreadCount || 0;

  // Handle manual refresh
  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      await refetch();
      setLastRefreshed(new Date());
      toast.success('Messages refreshed successfully');
    } catch (error) {
      toast.error('Failed to refresh messages');
    } finally {
      setTimeout(() => setIsRefreshing(false), 500); // Small delay for visual feedback
    }
  };

  // Update last refreshed on successful data fetch
  useEffect(() => {
    if (conversationsResponse && !isLoading && !isFetching) {
      setLastRefreshed(new Date());
    }
  }, [conversationsResponse, isLoading, isFetching]);

  // Forward message mutation
  const forwardMutation = useMutation({
    mutationFn: async ({ conversationId, message, includeContext }) => {
      return await interceptAPI.forwardToVA(conversationId, {
        message,
        includeContext
      });
    },
    onSuccess: () => {
      toast.success('Message successfully forwarded to VA');
      queryClient.invalidateQueries({ queryKey: ['intercepted-conversations'] });
      setForwardMessage('');
      setSelectedConversation(null);
    },
    onError: (error) => {
      toast.error(error.response?.data?.error || 'Failed to forward message');
    }
  });

  // Reply to business mutation
  const replyMutation = useMutation({
    mutationFn: async ({ conversationId, message }) => {
      return await interceptAPI.replyToBusiness(conversationId, { message });
    },
    onSuccess: () => {
      toast.success('Reply sent to business');
      queryClient.invalidateQueries({ queryKey: ['intercepted-conversations'] });
      setReplyMessage('');
      setSelectedConversation(null);
    },
    onError: (error) => {
      toast.error(error.response?.data?.error || 'Failed to send reply');
    }
  });

  // Add admin note mutation
  const noteMutation = useMutation({
    mutationFn: async ({ conversationId, notes }) => {
      return await interceptAPI.updateInterceptNotes(conversationId, { notes });
    },
    onSuccess: () => {
      toast.success('Admin notes updated');
      queryClient.invalidateQueries({ queryKey: ['intercepted-conversations'] });
      setAdminNote('');
    },
    onError: (error) => {
      toast.error(error.response?.data?.error || 'Failed to update notes');
    }
  });

  // Handle forward action
  const handleForward = (conversation) => {
    if (!forwardMessage.trim()) {
      toast.error('Please enter a message to forward');
      return;
    }

    forwardMutation.mutate({
      conversationId: conversation._id,
      message: forwardMessage,
      includeContext: true
    });
  };

  // Handle reply action
  const handleReply = (conversation) => {
    if (!replyMessage.trim()) {
      toast.error('Please enter a reply message');
      return;
    }

    replyMutation.mutate({
      conversationId: conversation._id,
      message: replyMessage
    });
  };

  // Handle add note action
  const handleAddNote = (conversation) => {
    if (!adminNote.trim()) {
      toast.error('Please enter a note');
      return;
    }

    noteMutation.mutate({
      conversationId: conversation._id,
      notes: adminNote
    });
  };

  // Toggle conversation expansion
  const toggleConversation = (conversationId) => {
    const newExpanded = new Set(expandedConversations);
    if (newExpanded.has(conversationId)) {
      newExpanded.delete(conversationId);
    } else {
      newExpanded.add(conversationId);
    }
    setExpandedConversations(newExpanded);
  };

  // Filter conversations based on search and status
  const filteredConversations = conversations?.filter(conv => {
    const matchesSearch = !searchTerm || 
      conv.business?.profile?.company?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      conv.business?.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      conv.va?.profile?.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      conv.va?.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      conv.lastMessage?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesFilter = filterStatus === 'all' ||
      (filterStatus === 'pending' && !conv.adminConversationId) ||
      (filterStatus === 'forwarded' && conv.adminConversationId) ||
      (filterStatus === 'unread' && !conv.isRead);

    return matchesSearch && matchesFilter;
  });

  // Use statistics from API response
  const stats = {
    total: apiStats.all,
    pending: apiStats.pending,
    forwarded: apiStats.forwarded,
    unread: unreadCount
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="admin-loading mb-4"></div>
          <p className="text-admin-600">Loading messages...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-white rounded-lg shadow-sm border border-admin-200 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-admin-900 flex items-center">
              <ChatBubbleLeftRightIcon className="h-8 w-8 mr-3 text-primary-600" />
              Intercepted Messages
            </h1>
            <p className="mt-1 text-sm text-admin-600">
              Manage and review business-to-VA conversations requiring admin attention
            </p>
            <p className="mt-1 text-xs text-admin-500">
              Last updated: {formatDistanceToNow(lastRefreshed, { addSuffix: true })}
            </p>
          </div>
          <button
            onClick={handleRefresh}
            disabled={isRefreshing || isFetching}
            className={`inline-flex items-center px-4 py-2 border border-admin-300 rounded-md shadow-sm text-sm font-medium text-admin-700 bg-white hover:bg-admin-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 transition-all duration-200 ${
              isRefreshing || isFetching ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            <ArrowPathIcon className={`h-4 w-4 mr-2 ${isRefreshing || isFetching ? 'animate-spin' : ''}`} />
            {isRefreshing || isFetching ? 'Refreshing...' : 'Refresh'}
          </button>
        </div>
      </div>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
        <div className="bg-white overflow-hidden shadow-sm rounded-lg border border-admin-200 hover:shadow-md transition-shadow duration-200">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <InboxIcon className="h-8 w-8 text-blue-600" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-admin-500 truncate">
                    Total Messages
                  </dt>
                  <dd className="flex items-baseline">
                    <div className="text-2xl font-semibold text-admin-900">
                      {stats.total}
                    </div>
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white overflow-hidden shadow-sm rounded-lg border border-admin-200 hover:shadow-md transition-shadow duration-200">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <CheckCircleIcon className="h-8 w-8 text-green-600" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-admin-500 truncate">
                    Forwarded
                  </dt>
                  <dd className="flex items-baseline">
                    <div className="text-2xl font-semibold text-admin-900">
                      {stats.forwarded}
                    </div>
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white overflow-hidden shadow-sm rounded-lg border border-admin-200 hover:shadow-md transition-shadow duration-200">
          <div className="p-5">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <EnvelopeIcon className="h-8 w-8 text-red-600" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-admin-500 truncate">
                    Unread
                  </dt>
                  <dd className="flex items-baseline">
                    <div className="text-2xl font-semibold text-admin-900">
                      {stats.unread}
                    </div>
                    {stats.unread > 0 && (
                      <span className="ml-2 flex h-2 w-2">
                        <span className="animate-ping absolute inline-flex h-2 w-2 rounded-full bg-red-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                      </span>
                    )}
                  </dd>
                </dl>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Search and Filters */}
      <div className="bg-white rounded-lg shadow-sm border border-admin-200 p-4">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-5 w-5 text-admin-400" />
              </div>
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="block w-full pl-10 pr-3 py-2 border border-admin-300 rounded-md leading-5 bg-white placeholder-admin-500 focus:outline-none focus:placeholder-admin-400 focus:ring-1 focus:ring-primary-500 focus:border-primary-500 sm:text-sm"
                placeholder="Search messages, businesses, or VAs..."
              />
            </div>
          </div>
          <div className="flex gap-2">
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="block pl-3 pr-10 py-2 text-base border-admin-300 focus:outline-none focus:ring-primary-500 focus:border-primary-500 sm:text-sm rounded-md"
            >
              <option value="all">All Messages</option>
              <option value="pending">Pending Review</option>
              <option value="forwarded">Forwarded</option>
              <option value="unread">Unread</option>
            </select>
          </div>
        </div>
      </div>

      {/* Messages List */}
      <div className="bg-white shadow-sm rounded-lg border border-admin-200">
        <div className="px-4 py-5 sm:p-6">
          {filteredConversations?.length === 0 ? (
            <div className="text-center py-12">
              <InboxIcon className="mx-auto h-12 w-12 text-admin-400" />
              <h3 className="mt-2 text-sm font-medium text-admin-900">No messages found</h3>
              <p className="mt-1 text-sm text-admin-500">
                {searchTerm || filterStatus !== 'all' 
                  ? 'Try adjusting your search or filter criteria'
                  : 'Business-to-VA conversations will appear here for review'}
              </p>
            </div>
          ) : (
            <div className="space-y-4">
              {filteredConversations?.map((conversation) => {
                const isExpanded = expandedConversations.has(conversation._id);
                const isSelected = selectedConversation?._id === conversation._id;
                
                return (
                  <div 
                    key={conversation._id} 
                    className={`border rounded-lg transition-all duration-200 ${
                      isSelected 
                        ? 'border-primary-500 shadow-lg' 
                        : 'border-admin-200 hover:border-admin-300 hover:shadow-md'
                    }`}
                  >
                    {/* Conversation Header */}
                    <div className="p-4">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          {/* Participants Section */}
                          <div className="flex items-center justify-between mb-3">
                            <div className="flex items-center space-x-3">
                              <button
                                onClick={() => toggleConversation(conversation._id)}
                                className="text-admin-500 hover:text-admin-700 transition-colors"
                              >
                                {isExpanded ? (
                                  <ChevronDownIcon className="h-5 w-5" />
                                ) : (
                                  <ChevronRightIcon className="h-5 w-5" />
                                )}
                              </button>
                              <div className="flex items-center space-x-2">
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    if (conversation.business?._id) {
                                      // Navigate to businesses page with the specific business ID as a query param
                                      navigate(`/businesses?highlight=${conversation.business._id}`);
                                    }
                                  }}
                                  className="flex items-center bg-blue-50 px-3 py-1 rounded-full hover:bg-blue-100 transition-colors cursor-pointer"
                                  title="View business profile"
                                >
                                  <BuildingOfficeIcon className="h-4 w-4 text-blue-600 mr-1" />
                                  <span className="text-sm font-medium text-blue-900 hover:underline">
                                    {conversation.business?.profile?.company || conversation.business?.email || 'Unknown Business'}
                                  </span>
                                </button>
                                <ArrowRightIcon className="h-4 w-4 text-admin-400" />
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    if (conversation.va?._id) {
                                      // Navigate to VAs page with the specific VA ID as a query param
                                      navigate(`/vas?highlight=${conversation.va._id}`);
                                    }
                                  }}
                                  className="flex items-center bg-green-50 px-3 py-1 rounded-full hover:bg-green-100 transition-colors cursor-pointer"
                                  title="View VA profile"
                                >
                                  <UserIcon className="h-4 w-4 text-green-600 mr-1" />
                                  <span className="text-sm font-medium text-green-900 hover:underline">
                                    {conversation.va?.profile?.name || conversation.va?.email || 'Unknown VA'}
                                  </span>
                                </button>
                              </div>
                            </div>
                            
                            {/* Status Badges */}
                            <div className="flex items-center space-x-2">
                              {!conversation.isRead && (
                                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
                                  <EnvelopeIcon className="h-3 w-3 mr-1" />
                                  Unread
                                </span>
                              )}
                              {conversation.adminStatus === 'awaiting_reply' ? (
                                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
                                  <ClockIcon className="h-3 w-3 mr-1" />
                                  Awaiting Reply
                                </span>
                              ) : conversation.adminStatus === 'forwarded' || conversation.adminConversationId ? (
                                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                                  <CheckCircleIcon className="h-3 w-3 mr-1" />
                                  Forwarded
                                </span>
                              ) : conversation.adminStatus === 'replied' ? (
                                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                                  <CheckCircleIcon className="h-3 w-3 mr-1" />
                                  Replied
                                </span>
                              ) : (
                                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">
                                  <ExclamationCircleIcon className="h-3 w-3 mr-1" />
                                  Pending
                                </span>
                              )}
                            </div>
                          </div>

                          {/* Last Message Preview */}
                          <div className="bg-admin-50 rounded-lg p-3 mb-3">
                            <div className="flex items-start justify-between mb-1">
                              <p className="text-xs font-medium text-admin-500 uppercase tracking-wider">
                                Last Message
                              </p>
                              <p className="text-xs text-admin-500">
                                {conversation.lastMessageAt && 
                                  formatDistanceToNow(new Date(conversation.lastMessageAt), { addSuffix: true })
                                }
                              </p>
                            </div>
                            <p className="text-sm text-admin-800 line-clamp-2">
                              {conversation.lastMessage || 'No message content'}
                            </p>
                          </div>

                          {/* Message Count and Timestamp */}
                          <div className="flex items-center justify-between text-xs text-admin-500">
                            <span className="flex items-center">
                              <ChatBubbleLeftRightIcon className="h-4 w-4 mr-1" />
                              {conversation.messages?.length || 0} messages in thread
                            </span>
                            <span>
                              Created {conversation.createdAt && 
                                format(new Date(conversation.createdAt), 'MMM d, yyyy h:mm a')
                              }
                            </span>
                          </div>

                          {/* Admin Notes Section */}
                          {conversation.adminNotes && (
                            <div className="mt-3 bg-yellow-50 border border-yellow-200 rounded-lg p-3">
                              <div className="flex items-start">
                                <DocumentTextIcon className="h-4 w-4 text-yellow-600 mt-0.5 mr-2 flex-shrink-0" />
                                <div className="flex-1">
                                  <p className="text-xs font-medium text-yellow-800 mb-1">Admin Notes</p>
                                  <p className="text-sm text-yellow-700">{conversation.adminNotes}</p>
                                </div>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Expanded Message Thread */}
                      {isExpanded && conversation.messages && (
                        <div className="mt-4 border-t border-admin-200 pt-4">
                          <h4 className="text-sm font-medium text-admin-700 mb-3">Message Thread</h4>
                          <div className="space-y-2 max-h-64 overflow-y-auto">
                            {conversation.messages.map((msg, idx) => (
                              <div 
                                key={idx}
                                className={`p-3 rounded-lg ${
                                  msg.sender === conversation.business?._id 
                                    ? 'bg-blue-50 ml-8' 
                                    : 'bg-green-50 mr-8'
                                }`}
                              >
                                <div className="flex items-center justify-between mb-1">
                                  <span className="text-xs font-medium text-admin-600">
                                    {msg.sender === conversation.business?._id ? 'Business' : 'VA'}
                                  </span>
                                  <span className="text-xs text-admin-500">
                                    {msg.timestamp && format(new Date(msg.timestamp), 'h:mm a')}
                                  </span>
                                </div>
                                <p className="text-sm text-admin-800">{msg.content}</p>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Action Buttons */}
                      {isSelected ? (
                        <div className="mt-4 space-y-3 border-t border-admin-200 pt-4">
                          {/* Forward to VA */}
                          {!conversation.adminConversationId && (
                            <div className="space-y-2">
                              <label className="block text-sm font-medium text-admin-700">
                                Forward to VA with message:
                              </label>
                              <div className="flex space-x-2">
                                <input
                                  type="text"
                                  value={forwardMessage}
                                  onChange={(e) => setForwardMessage(e.target.value)}
                                  placeholder="Hi, you have a new inquiry from a business..."
                                  className="flex-1 px-3 py-2 border border-admin-300 rounded-md shadow-sm placeholder-admin-400 focus:ring-primary-500 focus:border-primary-500 sm:text-sm"
                                />
                                <button
                                  onClick={() => handleForward(conversation)}
                                  disabled={forwardMutation.isLoading}
                                  className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200"
                                >
                                  {forwardMutation.isLoading ? (
                                    <div className="admin-loading-small mr-2" />
                                  ) : (
                                    <PaperAirplaneIcon className="h-4 w-4 mr-2" />
                                  )}
                                  Forward
                                </button>
                              </div>
                            </div>
                          )}

                          {/* Reply to Business */}
                          <div className="space-y-2">
                            <label className="block text-sm font-medium text-admin-700">
                              Reply to business:
                            </label>
                            <div className="flex space-x-2">
                              <input
                                type="text"
                                value={replyMessage}
                                onChange={(e) => setReplyMessage(e.target.value)}
                                placeholder="Thank you for your inquiry. An admin will review this..."
                                className="flex-1 px-3 py-2 border border-admin-300 rounded-md shadow-sm placeholder-admin-400 focus:ring-primary-500 focus:border-primary-500 sm:text-sm"
                              />
                              <button
                                onClick={() => handleReply(conversation)}
                                disabled={replyMutation.isLoading}
                                className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200"
                              >
                                {replyMutation.isLoading ? (
                                  <div className="admin-loading-small mr-2" />
                                ) : (
                                  <PaperAirplaneIcon className="h-4 w-4 mr-2" />
                                )}
                                Reply
                              </button>
                            </div>
                          </div>

                          {/* Add Note */}
                          <div className="space-y-2">
                            <label className="block text-sm font-medium text-admin-700">
                              Add admin note:
                            </label>
                            <div className="flex space-x-2">
                              <input
                                type="text"
                                value={adminNote}
                                onChange={(e) => setAdminNote(e.target.value)}
                                placeholder="Note about this conversation..."
                                className="flex-1 px-3 py-2 border border-admin-300 rounded-md shadow-sm placeholder-admin-400 focus:ring-primary-500 focus:border-primary-500 sm:text-sm"
                              />
                              <button
                                onClick={() => handleAddNote(conversation)}
                                disabled={noteMutation.isLoading}
                                className="inline-flex items-center px-4 py-2 border border-admin-300 rounded-md shadow-sm text-sm font-medium text-admin-700 bg-white hover:bg-admin-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200"
                              >
                                {noteMutation.isLoading ? (
                                  <div className="admin-loading-small mr-2" />
                                ) : (
                                  <DocumentTextIcon className="h-4 w-4 mr-2" />
                                )}
                                Add Note
                              </button>
                            </div>
                          </div>

                          <div className="flex justify-end">
                            <button
                              onClick={() => {
                                setSelectedConversation(null);
                                setForwardMessage('');
                                setReplyMessage('');
                                setAdminNote('');
                              }}
                              className="text-sm text-admin-500 hover:text-admin-700 transition-colors"
                            >
                              Cancel
                            </button>
                          </div>
                        </div>
                      ) : (
                        <div className="mt-4 flex justify-between items-center">
                          <button
                            onClick={() => toggleConversation(conversation._id)}
                            className="text-sm text-primary-600 hover:text-primary-700 font-medium transition-colors"
                          >
                            {isExpanded ? 'Hide Details' : 'View Thread'}
                          </button>
                          <button
                            onClick={() => {
                              setSelectedConversation(conversation);
                              setForwardMessage('');
                              setReplyMessage('');
                              setAdminNote('');
                            }}
                            className="inline-flex items-center px-4 py-2 border border-admin-300 rounded-md shadow-sm text-sm font-medium text-admin-700 bg-white hover:bg-admin-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 transition-all duration-200"
                          >
                            Manage Conversation
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default InterceptedMessages;