import React from 'react';
import { Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { ConfigProvider, App as AntApp } from 'antd';
import { useAuth } from './contexts/AuthContext';
import { SessionProvider } from './contexts/SessionContext';
import { NotificationProvider } from './components/common/NotificationSystem';
import { customTheme } from './theme';
import ModernLoginPage from './components/auth/ModernLoginPage';
import ModernDashboard from './components/dashboard/ModernDashboard';
import ModernLayout from './components/layout/ModernLayout';
import VAManagement from './pages/VAManagement';
import BusinessManagement from './pages/BusinessManagement';
import UserManagement from './pages/UserManagement';
import Announcements from './pages/Announcements';
import InterceptedMessages from './pages/InterceptedMessages';
import Analytics from './pages/Analytics';
import Settings from './pages/Settings';
import SystemSettings from './pages/SystemSettings';
import LoadingSpinner from './components/common/LoadingSpinner';
import ErrorBoundary from './components/common/ErrorBoundary';
import OAuthCallback from './pages/OAuthCallback';
import AcceptInvitation from './pages/AcceptInvitation';
import './App.css';

// Main App Component - BrowserRouter and AuthProvider are in index.js
const App = () => {
  return (
    <ErrorBoundary>
      <ConfigProvider theme={customTheme}>
        <AntApp>
          <SessionProvider>
            <NotificationProvider>
              <AppContent />
            </NotificationProvider>
          </SessionProvider>
        </AntApp>
      </ConfigProvider>
    </ErrorBoundary>
  );
};

// App Content Component (inside AuthProvider context)
const AppContent = () => {
  const { isAuthenticated, isLoading } = useAuth();

  // Show loading spinner while checking auth status
  if (isLoading) {
    return <LoadingSpinner />;
  }

  return (
    <div className="App">
      <Routes>
        {/* Public Routes - only accessible when NOT authenticated */}
        <Route 
          path="/login" 
          element={
            isAuthenticated ? <Navigate to="/dashboard" replace /> : <ModernLoginPage />
          } 
        />
        <Route path="/auth/callback" element={<OAuthCallback />} />
        <Route path="/accept-invitation/:token" element={<AcceptInvitation />} />
        
        {/* Protected Admin Routes - Wrapped in ModernLayout */}
        <Route element={<ProtectedRoute />}>
          <Route element={<ModernLayout />}>
            <Route path="/" element={<Navigate to="/dashboard" replace />} />
            <Route path="/dashboard" element={<ModernDashboard />} />
            <Route path="/va-management" element={<VAManagement />} />
            <Route path="/business-management" element={<BusinessManagement />} />
            <Route path="/users" element={<UserManagement />} />
            <Route path="/intercepted-messages" element={<InterceptedMessages />} />
            <Route path="/announcements" element={<Announcements />} />
            <Route path="/analytics" element={<Analytics />} />
            <Route path="/settings" element={<Settings />} />
            <Route path="/system-settings" element={<SystemSettings />} />
          </Route>
        </Route>
        
        {/* Catch all - redirect to login if not authenticated, dashboard if authenticated */}
        <Route 
          path="*" 
          element={
            isAuthenticated ? <Navigate to="/dashboard" replace /> : <Navigate to="/login" replace />
          } 
        />
      </Routes>
    </div>
  );
};

// Protected Route Component (inside AuthProvider context)
const ProtectedRoute = () => {
  const { isAuthenticated, isLoading, user } = useAuth();

  console.log('[ProtectedRoute] State:', { isAuthenticated, isLoading, userEmail: user?.email, isAdmin: user?.admin });

  // Don't render anything while loading
  if (isLoading) {
    console.log('[ProtectedRoute] Still loading, showing spinner');
    return <LoadingSpinner />;
  }

  // Redirect to login if not authenticated
  if (!isAuthenticated) {
    console.log('[ProtectedRoute] Not authenticated, redirecting to login');
    return <Navigate to="/login" replace />;
  }

  // Check if user has admin role
  const isAdmin = user?.admin === true;
  console.log('[ProtectedRoute] Admin check - user.admin:', user?.admin, 'isAdmin:', isAdmin);
  
  if (!isAdmin) {
    console.log('[ProtectedRoute] User is not admin, showing access denied');
    return (
      <div className="min-h-screen flex items-center justify-center bg-admin-50">
        <div className="max-w-md w-full bg-white shadow-lg rounded-lg p-6">
          <div className="text-center">
            <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-danger-100">
              <svg className="h-6 w-6 text-danger-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
              </svg>
            </div>
            <h3 className="mt-2 text-sm font-medium text-admin-900">Access Denied</h3>
            <p className="mt-1 text-sm text-admin-500">
              You don't have permission to access the admin panel.
            </p>
          </div>
        </div>
      </div>
    );
  }

  console.log('[ProtectedRoute] User is admin, rendering Outlet');
  return <Outlet />;
};

export default App;
