import React, { createContext, useContext, useState, useEffect } from 'react';
import { notification, Badge, Button, List, Typography, Space, Tag, Avatar } from 'antd';
import {
  BellOutlined,
  CheckCircleOutlined,
  ExclamationCircleOutlined,
  InfoCircleOutlined,
  CloseOutlined,
} from '@ant-design/icons';

const { Text } = Typography;

const NotificationContext = createContext();

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within a NotificationProvider');
  }
  return context;
};

export const NotificationProvider = ({ children }) => {
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  // Sample notifications - replace with real data from API
  const sampleNotifications = [
    {
      id: 1,
      type: 'success',
      title: 'New VA Registration',
      message: 'Sarah Johnson has completed her registration and is ready for approval.',
      timestamp: new Date(Date.now() - 5 * 60 * 1000), // 5 minutes ago
      read: false,
      avatar: null,
    },
    {
      id: 2,
      type: 'warning',
      title: 'System Maintenance',
      message: 'Scheduled maintenance will begin at 2:00 AM UTC. Expected downtime: 30 minutes.',
      timestamp: new Date(Date.now() - 2 * 60 * 60 * 1000), // 2 hours ago
      read: false,
      avatar: null,
    },
    {
      id: 3,
      type: 'info',
      title: 'New Message Intercepted',
      message: 'A new message has been intercepted and requires review.',
      timestamp: new Date(Date.now() - 4 * 60 * 60 * 1000), // 4 hours ago
      read: true,
      avatar: null,
    },
    {
      id: 4,
      type: 'error',
      title: 'API Rate Limit Warning',
      message: 'API rate limit is approaching 80% of the daily limit.',
      timestamp: new Date(Date.now() - 6 * 60 * 60 * 1000), // 6 hours ago
      read: true,
      avatar: null,
    },
  ];

  useEffect(() => {
    setNotifications(sampleNotifications);
    setUnreadCount(sampleNotifications.filter(n => !n.read).length);
  }, []);

  const showNotification = (type, title, message, duration = 4.5) => {
    const config = {
      message: title,
      description: message,
      duration,
      placement: 'topRight',
    };

    switch (type) {
      case 'success':
        notification.success(config);
        break;
      case 'error':
        notification.error(config);
        break;
      case 'warning':
        notification.warning(config);
        break;
      case 'info':
      default:
        notification.info(config);
        break;
    }
  };

  const addNotification = (notification) => {
    const newNotification = {
      id: Date.now(),
      timestamp: new Date(),
      read: false,
      ...notification,
    };

    setNotifications(prev => [newNotification, ...prev]);
    setUnreadCount(prev => prev + 1);

    // Show toast notification
    showNotification(
      newNotification.type,
      newNotification.title,
      newNotification.message
    );
  };

  const markAsRead = (id) => {
    setNotifications(prev =>
      prev.map(notification =>
        notification.id === id
          ? { ...notification, read: true }
          : notification
      )
    );
    setUnreadCount(prev => Math.max(0, prev - 1));
  };

  const markAllAsRead = () => {
    setNotifications(prev =>
      prev.map(notification => ({ ...notification, read: true }))
    );
    setUnreadCount(0);
  };

  const removeNotification = (id) => {
    const notification = notifications.find(n => n.id === id);
    if (notification && !notification.read) {
      setUnreadCount(prev => Math.max(0, prev - 1));
    }
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'success':
        return <CheckCircleOutlined style={{ color: '#52c41a' }} />;
      case 'error':
        return <ExclamationCircleOutlined style={{ color: '#ff4d4f' }} />;
      case 'warning':
        return <ExclamationCircleOutlined style={{ color: '#faad14' }} />;
      case 'info':
      default:
        return <InfoCircleOutlined style={{ color: '#1890ff' }} />;
    }
  };

  const getNotificationColor = (type) => {
    switch (type) {
      case 'success':
        return 'green';
      case 'error':
        return 'red';
      case 'warning':
        return 'orange';
      case 'info':
      default:
        return 'blue';
    }
  };

  const formatTimestamp = (timestamp) => {
    const now = new Date();
    const diff = now - timestamp;
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes}m ago`;
    if (hours < 24) return `${hours}h ago`;
    return `${days}d ago`;
  };

  const NotificationList = () => (
    <List
      dataSource={notifications}
      renderItem={(item) => (
        <List.Item
          style={{
            backgroundColor: item.read ? 'transparent' : '#f6ffed',
            padding: '12px 16px',
            borderBottom: '1px solid #f0f0f0',
          }}
        >
          <List.Item.Meta
            avatar={
              <Avatar
                size="small"
                icon={getNotificationIcon(item.type)}
                style={{ backgroundColor: 'transparent' }}
              />
            }
            title={
              <Space>
                <Text strong={!item.read}>{item.title}</Text>
                <Tag color={getNotificationColor(item.type)} size="small">
                  {item.type}
                </Tag>
                {!item.read && <Badge status="processing" />}
              </Space>
            }
            description={
              <div>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  {item.message}
                </Text>
                <div style={{ marginTop: 4 }}>
                  <Text type="secondary" style={{ fontSize: 11 }}>
                    {formatTimestamp(item.timestamp)}
                  </Text>
                </div>
              </div>
            }
          />
          <Space>
            {!item.read && (
              <Button
                type="text"
                size="small"
                onClick={() => markAsRead(item.id)}
              >
                Mark as read
              </Button>
            )}
            <Button
              type="text"
              size="small"
              icon={<CloseOutlined />}
              onClick={() => removeNotification(item.id)}
            />
          </Space>
        </List.Item>
      )}
    />
  );

  const value = {
    notifications,
    unreadCount,
    addNotification,
    markAsRead,
    markAllAsRead,
    removeNotification,
    showNotification,
    NotificationList,
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
};
