import React, { useState, useEffect } from 'react';
import { useNavigate, Navigate } from 'react-router-dom';
import {
  Card,
  Form,
  Input,
  Button,
  Typography,
  Space,
  Alert,
  Divider,
  Row,
  Col,
  theme,
} from 'antd';
import {
  UserOutlined,
  LockOutlined,
  EyeInvisibleOutlined,
  EyeTwoTone,
  HomeOutlined,
} from '@ant-design/icons';
import { useAuth } from '../../contexts/AuthContext';

const { Title, Text, Link } = Typography;

const ModernLoginPage = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login, isAuthenticated, isLoading: authLoading } = useAuth();
  const navigate = useNavigate();
  const { token } = theme.useToken();

  // Redirect if already authenticated
  useEffect(() => {
    console.log('[ModernLoginPage] Auth state:', { isAuthenticated, authLoading });
    if (isAuthenticated && !authLoading) {
      console.log('[ModernLoginPage] User already authenticated, redirecting to dashboard');
      navigate('/dashboard', { replace: true });
    }
  }, [isAuthenticated, authLoading, navigate]);

  const onFinish = async (values) => {
    setLoading(true);
    setError('');
    
    try {
      console.log('[ModernLoginPage] Attempting login with:', values.email);
      const result = await login({ email: values.email, password: values.password });
      console.log('[ModernLoginPage] Login result:', result);
      
      if (result && result.success) {
        console.log('[ModernLoginPage] Login successful, navigating to dashboard');
        // Force navigation after successful login
        setTimeout(() => {
          navigate('/dashboard', { replace: true });
        }, 100);
      }
    } catch (err) {
      console.error('[ModernLoginPage] Login error:', err);
      setError(err.response?.data?.error || err.message || 'Login failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // If already authenticated, redirect to dashboard
  if (isAuthenticated && !authLoading) {
    return <Navigate to="/dashboard" replace />;
  }

  return (
    <div
      style={{
        minHeight: '100vh',
        background: `linear-gradient(135deg, ${token.colorPrimary} 0%, ${token.colorPrimary}dd 100%)`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '20px',
      }}
    >
      <Row justify="center" style={{ width: '100%', maxWidth: 1200 }}>
        <Col xs={24} sm={20} md={16} lg={12} xl={10}>
          <Card
            style={{
              borderRadius: token.borderRadiusLG,
              boxShadow: '0 20px 40px rgba(0, 0, 0, 0.1)',
              border: 'none',
            }}
            bodyStyle={{ padding: '48px' }}
          >
            {/* Header */}
            <div style={{ textAlign: 'center', marginBottom: 32 }}>
              <div
                style={{
                  width: 64,
                  height: 64,
                  borderRadius: '50%',
                  background: `linear-gradient(135deg, ${token.colorPrimary}, ${token.colorPrimary}dd)`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  margin: '0 auto 16px',
                }}
              >
                <HomeOutlined style={{ fontSize: 28, color: 'white' }} />
              </div>
              <Title level={2} style={{ margin: 0, color: token.colorText }}>
                Welcome Back
              </Title>
              <Text type="secondary" style={{ fontSize: 16 }}>
                Sign in to Linkage VA Hub Admin Panel
              </Text>
            </div>

            {/* Error Alert */}
            {error && (
              <Alert
                message={error}
                type="error"
                showIcon
                style={{ marginBottom: 24 }}
                closable
                onClose={() => setError('')}
              />
            )}

            {/* Login Form */}
            <Form
              name="login"
              onFinish={onFinish}
              layout="vertical"
              size="large"
              autoComplete="off"
            >
              <Form.Item
                name="email"
                label="Email Address"
                rules={[
                  { required: true, message: 'Please input your email!' },
                  { type: 'email', message: 'Please enter a valid email!' },
                ]}
              >
                <Input
                  prefix={<UserOutlined style={{ color: token.colorTextTertiary }} />}
                  placeholder="admin@linkage.ph"
                  style={{ borderRadius: token.borderRadius }}
                />
              </Form.Item>

              <Form.Item
                name="password"
                label="Password"
                rules={[{ required: true, message: 'Please input your password!' }]}
              >
                <Input.Password
                  prefix={<LockOutlined style={{ color: token.colorTextTertiary }} />}
                  placeholder="Enter your password"
                  iconRender={(visible) => (visible ? <EyeTwoTone /> : <EyeInvisibleOutlined />)}
                  style={{ borderRadius: token.borderRadius }}
                />
              </Form.Item>

              <Form.Item style={{ marginBottom: 24 }}>
                <Button
                  type="primary"
                  htmlType="submit"
                  loading={loading}
                  block
                  style={{
                    height: 48,
                    borderRadius: token.borderRadius,
                    fontSize: 16,
                    fontWeight: 500,
                  }}
                >
                  Sign In
                </Button>
              </Form.Item>
            </Form>

            <Divider>
              <Text type="secondary">Quick Access</Text>
            </Divider>

            {/* Demo Credentials */}
            <Card
              size="small"
              style={{
                background: token.colorFillAlter,
                border: `1px solid ${token.colorBorderSecondary}`,
                marginBottom: 16,
              }}
            >
              <Space direction="vertical" style={{ width: '100%' }}>
                <Text strong style={{ fontSize: 14 }}>Demo Credentials:</Text>
                <Text code style={{ fontSize: 12 }}>
                  Email: admin@linkage.ph
                </Text>
                <Text code style={{ fontSize: 12 }}>
                  Password: admin123
                </Text>
              </Space>
            </Card>

            {/* Footer */}
            <div style={{ textAlign: 'center', marginTop: 24 }}>
              <Text type="secondary" style={{ fontSize: 12 }}>
                © 2025 Linkage VA Hub. All rights reserved.
              </Text>
            </div>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default ModernLoginPage;
