import React from 'react';
import { Result, Button, Card, Typography, Space } from 'antd';
import { ReloadOutlined, HomeOutlined, BugOutlined } from '@ant-design/icons';

const { Title, Text, Paragraph } = Typography;

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render will show the fallback UI
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // Log error to console and potentially to error reporting service
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    
    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // Here you could send error to error reporting service
    // Example: logErrorToService(error, errorInfo);
  }

  handleReload = () => {
    window.location.reload();
  };

  handleGoHome = () => {
    window.location.href = '/dashboard';
  };

  render() {
    if (this.state.hasError) {
      // Custom error UI
      return (
        <div
          style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '20px',
            background: '#f5f5f5',
          }}
        >
          <Card
            style={{
              maxWidth: 600,
              width: '100%',
              textAlign: 'center',
            }}
          >
            <Result
              status="error"
              icon={<BugOutlined style={{ fontSize: 64, color: '#ff4d4f' }} />}
              title="Something went wrong"
              subTitle="We're sorry, but something unexpected happened. Our team has been notified."
              extra={[
                <Space key="actions" size="middle">
                  <Button
                    type="primary"
                    icon={<ReloadOutlined />}
                    onClick={this.handleReload}
                  >
                    Reload Page
                  </Button>
                  <Button
                    icon={<HomeOutlined />}
                    onClick={this.handleGoHome}
                  >
                    Go to Dashboard
                  </Button>
                </Space>,
              ]}
            />

            {/* Error Details (only in development) */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <Card
                size="small"
                title="Error Details (Development Only)"
                style={{
                  marginTop: 24,
                  textAlign: 'left',
                  background: '#fff2f0',
                  border: '1px solid #ffccc7',
                }}
              >
                <Title level={5}>Error:</Title>
                <Paragraph
                  code
                  style={{
                    background: '#fff',
                    padding: 12,
                    borderRadius: 4,
                    fontSize: 12,
                    wordBreak: 'break-all',
                  }}
                >
                  {this.state.error && this.state.error.toString()}
                </Paragraph>

                <Title level={5}>Stack Trace:</Title>
                <Paragraph
                  code
                  style={{
                    background: '#fff',
                    padding: 12,
                    borderRadius: 4,
                    fontSize: 12,
                    whiteSpace: 'pre-wrap',
                    wordBreak: 'break-all',
                    maxHeight: 200,
                    overflow: 'auto',
                  }}
                >
                  {this.state.errorInfo.componentStack}
                </Paragraph>
              </Card>
            )}

            {/* Help Text */}
            <div style={{ marginTop: 24 }}>
              <Text type="secondary">
                If this problem persists, please contact our support team or try refreshing the page.
              </Text>
            </div>
          </Card>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
